@classmethod
def hstack(cls, *args):
    """Return a matrix formed by joining args horizontally (i.e.
    by repeated application of row_join).

    Examples
    ========

    >>> from sympy.matrices import Matrix, eye
    >>> Matrix.hstack(eye(2), 2*eye(2))
    Matrix([
    [1, 0, 2, 0],
    [0, 1, 0, 2]])
    """
    if len(args) == 0:
        return cls._new()

    rows = set(arg.rows for arg in args)
    if len(rows) != 1:
        raise ShapeError("Matrixes must have matching rows")
    row = rows.pop()

    # filter out empty matrices
    args = [arg for arg in args if arg.cols != 0]

    if len(args) == 0:
        # if all matrices were filtered out, we have no columns
        return cls._new(row, 0)

    kls = type(args[0])
    return reduce(kls.row_join, args)
```

